import{U as s,V as c,X as b,Y as l,Z as C,_ as rn,a0 as K,a1 as O,a2 as A,a3 as U,a4 as on,C as z,$ as Xn,a5 as yn,o as w,n as E,D,a6 as _n,a7 as j,a8 as hn}from"./index-DF_V0nly.js";const Jn={main:[{id:"chars",name:"Nhân vật",icon:"nhan-vat",group:"Hồ sơ",hint:"Thông tin, Nét Sao, hồ sơ"},{id:"team",name:"Đội hình",icon:"doi-hinh",group:"Hồ sơ",hint:"4 đội lưu sẵn"},{id:"wish",name:"Ước nguyện",icon:"uoc-nguyen",group:"Ước nguyện",hint:"Bảo Hộ Vận Sao, lịch sử"},{id:"bag",name:"Túi đồ",icon:"tui-do",group:"Hành trang",hint:"Vật phẩm và câu chuyện"},{id:"weapons",name:"Kho vũ khí",icon:"danh",group:"Hành trang",hint:"Nâng cấp, tinh luyện, Lò Rèn"},{id:"quests",name:"Nhiệm vụ",icon:"nhiem-vu",group:"Hành trang",hint:"Đang làm, đã xong"},{id:"map",name:"Bản đồ",icon:"ban-do",group:"Hành trang",hint:"Dịch chuyển, đánh dấu"},{id:"codex",name:"Bách khoa",icon:"huong-dan",group:"Hành trang",hint:"Những gì đã thấy"},{id:"daily",name:"Ủy thác",icon:"uy-thac",group:"Thử thách",hint:"Việc mỗi ngày"},{id:"tower",name:"Tháp Tinh Tú",icon:"thap",group:"Thử thách",hint:"12 tầng"},{id:"boss",name:"Thảo phạt Hắc Giao",icon:"canh-bao",group:"Thử thách",hint:"Ác long dưới núi"},{id:"settings",name:"Cài đặt",icon:"cai-dat",group:"Hệ thống",hint:"Âm thanh, điều khiển"}],quick:["wish","team","daily"],transitionMs:180,combatLock:{radius:360,message:"Không thể đổi đội khi đang chiến đấu"},affinity:{perSecond:.05,perKill:1,levels:[10,30,60,100,150,220,300,400,520]},profile:[{file:"ho-so",name:"Hồ sơ",level:1,perSection:0},{file:"ngoai-hinh",name:"Ngoại hình",level:1,perSection:0},{file:"loi-thoai",name:"Lời thoại",level:1,perSection:1},{file:"tieu-su",name:"Tiểu sử",level:2,perSection:1},{file:"quan-he",name:"Quan hệ",level:3,perSection:1},{file:"ky-nang-truyen",name:"Chuyện kỹ năng",level:4,perSection:0},{file:"nhiem-vu-nhan-vat",name:"Chuyện riêng",level:6,perSection:1}],npcs:[{id:"thu-vong",name:"Bà Cả Thu Vọng",role:"Hội Đền Trăng",at:"center"},{id:"trum-kha",name:"Bà Trùm Kha",role:"Phường Đá Ngọc",at:"statue:2"},{id:"bay-song",name:"Bà Bảy Sóng",role:"Đoàn Thuyền Buôn Gió Nồm",at:"dir:200:22"},{id:"cao-luy",name:"Quan Trấn Thủ Cao Lũy",role:"Quân Trấn Thủ",at:"start"},{id:"ky-lam",name:"Đầu Sổ Kỳ Lam",role:"Người Đếm Sao",at:"dir:280:40"}],map:{zoomMin:1,zoomMax:4,maxMarks:30}},Un={types:[{id:"vu-khi",name:"Vũ khí huyền thoại",icon:"danh"},{id:"di-vat",name:"Di vật",icon:"sao"},{id:"sach-co",name:"Sách cổ",icon:"huong-dan"},{id:"manh-sao",name:"Mảnh sao vỡ",icon:"da-sao"},{id:"nguyen-lieu",name:"Nguyên liệu",icon:"tui-do"}],drops:{chest:[{chance:.6,pool:["kiem-sat-cu","cung-tre","sach-phep-rach","thuong-go","ngoc-vo","bua-giay","dai-kiem-gi"]},{chance:.12,pool:["muoi-dem-nuoc-den","so-sao-thu-nhat","bai-ru-ba-hien","sach-da-cua-phuong","hoa-van-tuyet-nam-phong-an","so-gach-ngoi-sao","luat-tram-duoc","thu-cua-nguoi-ganh-nguyen"]},{chance:.04,pool:["trong-cua-ong-duc-trong","luoi-cua-ba-luoi","den-nang-van-dang","chuong-bac-den-trang","loi-sao-bia-dong","duc-cua-to-khuyet","mat-na-go-troi"]}],enemy:[{chance:.04,pool:["kiem-sat-cu","cung-tre","sach-phep-rach","thuong-go","ngoc-vo","bua-giay","dai-kiem-gi"]}],boss:[{chance:1,pool:["loi-sao-bia-dong"]}]},items:[{id:"quang-tinh-luyen-tho",name:"Quặng Tinh Luyện Thô",type:"nguyen-lieu",rarity:3,region:"Đảo Lạc",story:"Cục quặng sẫm nhặt ở bãi sông sau mùa lũ. Thợ rèn làng nung lên rồi rắc vào lò để thép nhớ thêm chút lửa."},{id:"quang-tinh-luyen",name:"Quặng Tinh Luyện",type:"nguyen-lieu",rarity:4,region:"Marevia",story:"Quặng đã lọc qua ba lò, gõ vào nghe tiếng ngân dài. Dùng để đánh thức một món binh khí còn ngủ."},{id:"quang-tinh-luyen-sao",name:"Quặng Tinh Luyện Sao",type:"nguyen-lieu",rarity:5,region:"Marevia",story:"Quặng lấy từ nơi sao rơi, lạnh tay dù để cạnh lửa. Binh khí muốn vượt giới hạn cũ phải có nó."},{id:"phoi-long-sao",name:"Phôi Lòng Sao",type:"nguyen-lieu",rarity:4,region:"Đảo Lạc",story:"Thỏi kim loại mang về từ Lòng Sao, còn ấm như vừa ra lò. Đủ tám thỏi, Lò Rèn sẽ đúc nên một binh khí mới."},{id:"sach-kinh-nghiem",name:"Sách Kinh Nghiệm",type:"nguyen-lieu",rarity:3,region:"Đảo Lạc",story:"Sổ tay ghi chép của những Hộ Tinh đi trước, mép giấy còn vết đất và vết mực. Đọc xong một cuốn, bước chân thấy vững hơn một chút.",profileKey:"books"},{id:"thuong-cua-kien",name:"Thương Của Kiên",type:"vu-khi",rarity:5,weapon:"Thương",region:"Đảo Lạc",story:"Cây thương gỗ lim bịt đồng của người lập Quân Trấn Thủ. Đã ba trăm năm treo ở Trại Bắc, mũi thương vẫn ấm như vừa rút khỏi giông. Lính mới phải chạm tay vào nó trước khi nhận việc."},{id:"luoi-may-aianga",name:"Lưỡi Mây Aianga",type:"vu-khi",rarity:5,weapon:"Thương",region:"Khokhtal",story:"Ngọn thương Aianga trao cho người Đảo Lạc đầu tiên chạy kịp cơn giông của bà. Cán làm từ một ống đá sét dài, khi cầm thì nghe tiếng vó ngựa. Đây là thương của Lôi Đình."},{id:"kiem-hong-dieu",name:"Kiếm Hồng Điểu",type:"vu-khi",rarity:5,weapon:"Kiếm đơn",region:"Đảo Lạc",story:"Thanh kiếm lưỡi cong nhẹ, chuôi khắc hình chim Lạc dang cánh. Dòng người giữ Đình truyền nó qua mười đời. Mỗi đời, cánh chim trên chuôi lại sáng thêm một chút."},{id:"cung-dinh-may",name:"Cung Đỉnh Mây",type:"vu-khi",rarity:5,weapon:"Cung",region:"Đảo Lạc",story:"Cây cung làm từ một thân trúc mọc trên Đỉnh Vọng Vân, nơi gió thổi không ngừng. Người Đếm Sao dùng nó bắn tín hiệu giữa các đài. Dây cung rung khi có sao băng ở xa."},{id:"bang-lan-nhat-thuc",name:"Băng Lan Nhất Thức",type:"vu-khi",rarity:5,weapon:"Kiếm đơn",region:"Shizukane",story:"Lưỡi kiếm rèn ở Xưởng Rèn Shimogane bằng thép trộn một mảnh sao rơi. Khi rút khỏi vỏ, hoa lan băng nở dọc sống kiếm rồi rụng xuống mà không tan. Kiếm này không phát ra tiếng khi chém."},{id:"dai-kiem-da-bia",name:"Đại Kiếm Đá Bia",type:"vu-khi",rarity:5,weapon:"Đại kiếm",region:"Đảo Lạc",story:"Thanh đại kiếm đẽo từ một tấm bia vỡ trong Mùa Nước Đen. Trên lưỡi còn mờ mờ chín cái tên mà không ai đọc trọn. Thợ đá nói nó nặng bằng cả lời hứa của chín người."},{id:"kiem-khong-ten-cua-lo-lon",name:"Kiếm Không Tên Của Lò Lớn",type:"vu-khi",rarity:5,weapon:"Kiếm đơn",region:"Marevia",story:"Thanh kiếm hoàn hảo Faber rèn thời Trăm Bến, nguyên nhân của một cuộc chiến giữa hai thành. Ông cắm nó ngược trên đe trong Lò Lớn. Chưa ai rút được nó ra, kể cả ông."},{id:"but-gio",name:"Bút Gió",type:"vu-khi",rarity:5,weapon:"Pháp khí",region:"Lũng Vân",story:"Cây bút lông Thính Phong dùng chép sổ suốt nghìn năm. Ngòi bút làm từ lông đuôi của một con hạc đã sống ba trăm tuổi. Viết lời dối bằng bút này thì nét mực tự bay đi."},{id:"cung-sung-bay-mua",name:"Cung Sừng Bảy Mùa",type:"vu-khi",rarity:5,weapon:"Cung",region:"Khokhtal",story:"Cung sừng ghép bảy lớp, mỗi lớp là sừng của một con dê núi ở một mùa cỏ khác nhau. Thợ làm mất bảy năm mới xong một cây. Người Cầm Cương đầu tiên dùng nó trong Hội Ba Môn."},{id:"duoc-da-ostad",name:"Đuốc Đá Ostad",type:"vu-khi",rarity:5,weapon:"Pháp khí",region:"Golbaran",story:"Ngọn đuốc bằng đất nung có khảm men xanh, ánh sáng của nó làm vữa đông nhanh gấp mười. Ostad Khesht cho mượn khi ai đó cần dựng nhà gấp trước cơn bão cát. Người mượn phải trả bằng một viên gạch khắc tên mình."},{id:"trong-cua-ong-duc-trong",name:"Trống Của Ông Đúc Trống",type:"di-vat",rarity:5,region:"Đảo Lạc",story:"Chiếc trống đồng đầu tiên của Đảo Lạc, đặt giữa Đình Trống Đồng. Mặt trống có ngôi sao mười hai cánh và một vòng chim Lạc bay ngược chiều kim đồng hồ. Gõ một tiếng, cả đảo nghe."},{id:"luoi-cua-ba-luoi",name:"Lưới Của Bà Lưới",type:"di-vat",rarity:5,region:"Đảo Lạc",story:"Một mảnh lưới đánh cá đã mục, sợi nào cũng lấp lánh bụi sao. Người ta nói Bà Lưới đã đan nó trong mười đêm chờ con. Mắt lưới cuối cùng chưa được thắt."},{id:"den-nang-van-dang",name:"Đèn Nàng Vạn Đăng",type:"di-vat",rarity:5,region:"Đảo Lạc",story:"Chiếc đèn lồng đầu tiên của Nàng Vạn Đăng, treo ở một góc hẻm trong Phố Cũ và chưa từng tắt. Giấy đèn đã vàng như lá khô mà không rách. Không ai thấy ai châm dầu cho nó."},{id:"chuong-bac-den-trang",name:"Chuông Bạc Đền Trăng",type:"di-vat",rarity:5,region:"Đảo Lạc",story:"Chiếc chuông bạc nhỏ của Người Giữ Đền Trăng. Tiếng chuông làm nước dịu lại và vết thương khép miệng. Mỗi đời người giữ đền khắc thêm một vòng trăng vào quai chuông."},{id:"loi-sao-bia-dong",name:"Lõi Sao Bia Đông",type:"di-vat",rarity:5,region:"Đảo Lạc",story:"Viên đá to bằng nắm tay, trong suốt, có một đốm sáng chuyển động như cá bơi. Đây là một trong bốn lõi giữ phong ấn Hắc Giao. Năm NS 1347 nó bị lấy đi khỏi bia."},{id:"duc-cua-to-khuyet",name:"Đục Của Tô Khuyết",type:"di-vat",rarity:5,region:"Đảo Lạc",story:"Chiếc đục đồng mòn vẹt, cán quấn dây mây. Bốn Bia Đá cổ được khắc bằng chính chiếc đục này. Phường Đá Ngọc cất nó trong hộp khóa ba lớp mà không nói vì sao."},{id:"mat-na-go-troi",name:"Mặt Nạ Gỗ Trôi",type:"di-vat",rarity:5,region:"Đảo Lạc",story:'Mặt nạ gỗ trôi dạt của Lão Neo, mặt trong khắc nguệch ngoạc bốn chữ "Trả con tôi về". Áp tai vào gỗ nghe được tiếng sóng. Gỗ vẫn mặn dù đã phơi khô.'},{id:"chuong-khong-qua-lac",name:"Chuông Không Quả Lắc",type:"di-vat",rarity:5,region:"Shizukane",story:"Chiếc chuông đồng không có quả lắc, lấy từ Cầu Kanehashi. Người Shizukane treo nó trước cửa để nhớ ba làng bị tuyết vùi. Có người nói nó đã kêu một lần, vào đêm Yukiyo thề im lặng."},{id:"gach-ten-dau-tien",name:"Gạch Tên Đầu Tiên",type:"di-vat",rarity:5,region:"Golbaran",story:"Viên gạch bùn khô đầu tiên Ostad Khesht nhận làm lễ, khắc tên một người chủ nhà đã bị cát xóa mờ. Ông mang nó theo người suốt nghìn năm. Ông nói đó là ngôi nhà ông thích nhất."},{id:"hat-thong-dau-tien",name:"Hạt Thông Đầu Tiên",type:"di-vat",rarity:5,region:"Purunae",story:"Một hạt thông to bằng ngón tay cái, nâu bóng, nằm trong hộp gỗ của Vương triều Rễ. Đây là hạt đầu tiên rụng từ Sonamu. Nó chưa bao giờ nảy mầm, và người ta tin nó đang chờ."},{id:"vong-nguyet-que-dong",name:"Vòng Nguyệt Quế Đồng",type:"di-vat",rarity:5,region:"Marevia",story:"Vòng nguyệt quế đúc bằng đồng, phần thưởng của Hội Tranh Tài Thợ năm Faber tự chấm mình hạng nhất. Ông chỉ đeo nó một ngày rồi tặng cho người thua. Người thua ấy là thợ Đảo Lạc."},{id:"soi-cuong-giong",name:"Sợi Cương Giông",type:"di-vat",rarity:5,region:"Khokhtal",story:"Một sợi dây cương bằng lông bờm ngựa giông, sờ vào tê tê như kiến bò. Người Cầm Cương được trao nó khi nhậm chức. Ai không bỏ cuộc giữa giông thì sợi dây không bao giờ đứt."},{id:"muoi-dem-nuoc-den",name:"Mười Đêm Nước Đen",type:"sach-co",rarity:4,region:"Lũng Vân",story:"Sách Ông Lái Gió viết về Mùa Nước Đen và trận phong ấn Hắc Giao. Có một trang bị xé, đúng chỗ lẽ ra ghi tên một trong Năm Người Giữ Đảo. Bản chép tay ở Các Nghe Gió còn nguyên trang ấy."},{id:"so-sao-thu-nhat",name:"Sổ Sao Thứ Nhất",type:"sach-co",rarity:4,region:"Đảo Lạc",story:"Cuốn sổ của Bà Đầu Sổ Thứ Nhất, chép tên sáu nghìn vì sao bằng mực pha bụi sao. Đọc dưới trăng thì những cái tên phát sáng. Mấy trang cuối ghi số sao mới mỗi năm, và con số giảm dần."},{id:"bai-ru-ba-hien",name:"Bài Ru Bà Hiên",type:"sach-co",rarity:4,region:"Đảo Lạc",story:"Tập bài hát ru Bà Khơi do Bà Cả đầu tiên của Hội Đền Trăng viết. Trẻ con trên đảo thuộc lòng bài đầu mà không biết nó dành cho ai. Bài cuối cùng chưa ai từng hát."},{id:"sach-da-cua-phuong",name:"Sách Đá Của Phường",type:"sach-co",rarity:4,region:"Đảo Lạc",story:"Không phải sách giấy mà là mười hai phiến đá mỏng xâu dây đồng, ghi cách khắc Bia Đá và cách giữ lõi sao. Phiến thứ mười hai bị đục xóa. Người xóa dùng đúng nét đục của người viết."},{id:"hoa-van-tuyet-nam-phong-an",name:"Hoa Văn Tuyết Năm Phong Ấn",type:"sach-co",rarity:4,region:"Shizukane",story:'Bản chép của Người Đọc Tuyết về những gì Yukiyo thấy năm NS 1052, vẽ bằng mực chàm trên giấy trắng. Nhìn lâu thì hoa văn như chuyển động. Ở góc cuối có một hoa văn chưa ai đọc được, giống chữ "xin lỗi".'},{id:"so-gach-ngoi-sao",name:"Sổ Gạch Ngôi Sao",type:"sach-co",rarity:4,region:"Golbaran",story:'Bản sao sổ sao của Người Đếm Sao, khắc trên ba trăm viên gạch men xanh trong Thành Tháp Gió. Ostad Khesht cho chép vì "giấy thì cháy, gạch thì không". Viên gạch cuối ghi năm NS 900 và một con số bị gạch chéo.'},{id:"luat-tram-duoc",name:"Luật Trăm Đuốc",type:"sach-co",rarity:4,region:"Marevia",story:'Bộ luật của cộng hòa Marevia, viết trên da và đọc to mỗi năm ở Quảng Trường Đuốc. Điều đầu tiên ghi: "Lửa là của người làm ra nó." Faber viết chú thích bên lề: "Ta đồng ý."'},{id:"thu-cua-nguoi-ganh-nguyen",name:"Thư Của Người Gánh Nguyện",type:"sach-co",rarity:4,region:"Không rõ",story:'Một bức thư không ký tên, mực đã nhạt, gửi "người sẽ đến sau". Trong thư chỉ có một lời ước được viết lại hàng nghìn lần bằng một nét chữ đều tăm tắp. Ở dòng cuối, nét chữ run lên.'},{id:"kiem-sat-cu",name:"Kiếm Sắt Cũ",type:"manh-sao",rarity:3,region:"Đảo Lạc",story:"Thanh kiếm của một người lính vô danh thời Nước Đen. Sắt đã xỉn, nhưng lưỡi vẫn sắc."},{id:"cung-tre",name:"Cung Tre",type:"manh-sao",rarity:3,region:"Đảo Lạc",story:"Cung tre của một đứa trẻ làng chài, dây cung là sợi gai bện. Nó từng bắn trúng một con cò và khóc cả ngày."},{id:"sach-phep-rach",name:"Sách Phép Rách",type:"manh-sao",rarity:3,region:"Đảo Lạc",story:"Nửa cuốn sách học phép của một Hộ Tinh già. Nửa còn lại chắc đang nằm dưới một vì sao nào đó."},{id:"thuong-go",name:"Thương Gỗ",type:"manh-sao",rarity:3,region:"Đảo Lạc",story:"Cây thương tập của dân binh Đảo Lạc. Cán gỗ đầy vết tay của nhiều thế hệ."},{id:"ngoc-vo",name:"Ngọc Vỡ",type:"manh-sao",rarity:3,region:"Đảo Lạc",story:"Mảnh ngọc bích từ Mỏ Ngọc Lòng Chảo, vỡ khi rơi theo sao băng. Một mặt vẫn còn hoa văn khắc dở."},{id:"bua-giay",name:"Bùa Giấy",type:"manh-sao",rarity:3,region:"Đảo Lạc",story:'Lá bùa giấy dó viết một lời ước nhỏ: "mong mai trời nắng". Có vẻ hôm đó trời đã nắng.'},{id:"dai-kiem-gi",name:"Đại Kiếm Gỉ",type:"manh-sao",rarity:3,region:"Đảo Lạc",story:"Đại kiếm đã gỉ của một thợ đá kiêm lính canh. Ông dùng nó để chặt đá nhiều hơn là đánh nhau."}]},Zn={creatures:[{id:"slime",name:"Giọt Nhầy",tag:"slime",habitat:"ruộng, bờ sông, rìa rừng Đảo Lạc. Biến thể có ở mọi vùng.",lore:'hạt nguyện nhỏ rơi xuống đất ẩm rồi đông thành khối nhầy trong. Chúng đi theo nhóm, bò về chỗ có tiếng người vì "nhớ" mình từng là lời ước của người.',weak:"chậm, dễ bị đẩy lùi. Phong thổi bay.",rumor:'"Giọt nhầy nào vỡ ra mà có tiếng cười là lời ước của trẻ con."',inGame:!0},{id:"goblin",name:"Yêu Rừng",tag:"goblin",habitat:"Rừng Trúc Mây.",lore:"dân rừng nhỏ bé, mặt xanh, tai dài, sống thành làng trên ngọn trúc. Trước đây chúng chỉ trộm cơm nắm của người đi rừng. Từ khi Hội Mặt Nạ đốt bãi trúc phía nam, chúng coi mọi người lạ là kẻ thù và lập trại ra tận bìa rừng.",weak:"Hỏa (sợ lửa vì bãi trúc bị đốt). Nếu đánh tan trại, chúng chạy về rừng chứ không biến mất.",rumor:'"Để một nắm xôi ở gốc trúc thì đêm đó Yêu Rừng không vào làng."',inGame:!0},{id:"archer",name:"Yêu Rừng Cung Thủ",tag:"archer",habitat:"Rừng Trúc Mây, trên cành cao.",lore:"Yêu Rừng lớn tuổi hơn, canh gác làng. Bắn mũi tên trúc từ xa.",weak:"Phong (gió làm lệch tên), đánh gần.",rumor:'"Nghe tiếng trúc gõ ba lần là Yêu Rừng Cung Thủ báo động."',inGame:!0},{id:"shaman",name:"Pháp Sư Mặt Nạ",tag:"shaman",habitat:"quanh các Bia Đá, trại quái, phế tích. Có ở mọi vùng.",lore:"thành viên cấp thấp của Hội Mặt Nạ (bậc Mặt Nạ Trắng có học phép). Họ là người thật, không phải quái. Họ dùng Nguyện Cặn chứa trong mặt nạ để bắn những cầu năng lượng tối.",weak:"đánh gần, ngắt phép. Khi bị đánh bại, mặt nạ nứt và họ bỏ chạy. Người chơi không bao giờ thấy mặt họ trong bản thử nghiệm.",rumor:'"Ai đeo mặt nạ trắng ba năm thì quên mặt mình."',inGame:!0},{id:"golem",name:"Hộ Vệ Đá Cổ",tag:"golem, tinh anh",habitat:"quanh Hang Hắc Giao và các phế tích Thời Nước Đen.",lore:"tượng đá Tô Khuyết khắc năm NS 1052 để canh miệng hang. Lõi chứa một mảnh sao nhỏ. Ba trăm năm qua, lõi bị Nguyện Cặn thấm vào nên tượng không còn phân biệt bạn thù, đánh mọi ai đến gần.",weak:"chậm, sau mỗi cú đập mạnh phải đứng nghỉ. Lõi sao lộ ra ở lưng. Lôi và Băng làm đá giòn.",rumor:'"Hộ Vệ Đá Cổ là Tô Khuyết hóa đá." (Sai, nhưng có lý do: mặt tượng được khắc theo mặt anh.)',inGame:!0},{id:"hacgiao",name:"Hắc Giao",tag:"hacgiao, boss",habitat:"Hang Hắc Giao, nối thông xuống Biển Lặng.",lore:"con giao (rồng nước không sừng) đen dài hàng trăm sải, thân bằng Nguyện Cặn đông lại. Nó không ăn, không ngủ, chỉ cuộn mình và **thì thầm** những lời ước chưa ai nghe.",weak:"giai đoạn 1 yếu với Lôi (Điện Cảm) và Băng (Đóng Băng). Giai đoạn 2 yếu với Băng (Siêu Dẫn) và Thổ (Kết Tinh làm khiên).",rumor:'"Đêm Vịnh Khơi đen, đừng nói lời ước thành tiếng, kẻo Hắc Giao nghe được mà học theo."',inGame:!0},{id:"cua-mai-dong",name:"Cua Mai Đồng",tag:null,habitat:"Bãi Sao Rơi, Làng Vạn Lưới, bờ đá Vịnh Khơi.",lore:"cua đá to như cái thúng. Mai của chúng bám đầy mảnh đồng vỡ từ những chiếc trống ở ba làng chìm. Bình thường hiền, chỉ đánh khi bị dẫm vào tổ.",weak:"bụng mềm. Lật ngửa bằng Phong (Khuếch Tán) hoặc đòn hất tung. Lôi lan qua mai đồng.",rumor:'"Gõ vào mai cua đồng mà nghe tiếng trống thì năm ấy được mùa cá."',inGame:!1},{id:"dom-dom-lac-loi",name:"Đom Đóm Lạc Lối",tag:null,habitat:"Rừng Trúc Mây, ruộng lúa đêm.",lore:'bầy đom đóm bị lời ước "mong được về nhà" của người lạc bám vào, nên mỗi bầy là một cơn lốc ánh sáng tìm đường. Chúng dẫn người lạc vào sâu hơn và chích điện ai đuổi theo.',weak:"Thủy (gây Điện Cảm làm cả bầy tê liệt). Đèn lồng của Mai Linh hút chúng lại.",rumor:'"Đom đóm bay thành vòng là có người lạc trong rừng."',inGame:!1},{id:"bong-can",name:"Bóng Cặn",tag:null,habitat:"Vịnh Khơi lúc nước đen, Hang Hắc Giao, Lòng Sao bị nhiễm bùn.",lore:'những mảnh Nguyện Cặn nhỏ tách khỏi Hắc Giao, mang hình người mờ đen. Mỗi Bóng Cặn lặp đi lặp lại một lời ước không thành, ví dụ "giá mà ta đã ở lại".',weak:"Hỏa (Bốc Hơi), ánh sáng của Bia Đá. Đứng gần Bia Đá thì chúng yếu đi.",rumor:'"Nghe Bóng Cặn nói đến câu thứ ba thì đừng đáp lại."',inGame:!1},{id:"trau-da-ngu",name:"Trâu Đá Ngủ",tag:"tinh anh",habitat:"Mỏ Ngọc Lòng Chảo, tầng sâu.",lore:"con trâu khổng lồ hóa đá từ thời Bảy Sao Xuống, ngủ cuộn trong lòng mỏ. Thợ mỏ đào sâu quá làm nó tỉnh dậy. Nó không ác, chỉ cáu vì bị đánh thức.",weak:"sau mỗi cú húc phải dừng lại thở. Thủy làm đá trơn khiến nó trượt ngã.",rumor:'"Thợ mỏ hát ru thì Trâu Đá ngủ tiếp." Thực tế đúng: nếu có Thủy Nguyệt trong đội, trận đấu ngắn hơn.',inGame:!1},{id:"linh-mat-na-trang",name:"Lính Mặt Nạ Trắng",tag:null,habitat:"mọi vùng, quanh trại của Hội Mặt Nạ.",lore:"thành viên mới của Hội Mặt Nạ, chưa học phép, dùng gậy và dao găm. Phần lớn là người nghèo, Người Tắt Sao, hoặc người trẻ giận đời.",weak:"thiếu kỷ luật. Nếu Pháp Sư Mặt Nạ đi cùng bị đánh bại, họ bỏ chạy.",rumor:'"Lính mặt nạ ban ngày là thợ, là phu, là người bán hàng ngay cạnh nhà mình."',inGame:!1}],places:[{id:"bai-sao-roi",name:"Bãi Sao Rơi",lore:"Bãi cát đen lấp lánh ở mũi nam, cát có những hạt sáng như mảnh sao. Nơi Bà Lưới thấy vì sao đầu tiên năm NS 1, và nơi Người Ước Nguyện tỉnh dậy.",secret:"Đào sâu một sải tay sẽ gặp lớp cát trắng như sứ, đó là nơi sao băng vàng chạm đất đêm đầu năm NS 1350.",at:"dir:180:34"},{id:"lang-van-luoi",name:"Làng Vạn Lưới",lore:"Làng chài lớn nhất đảo, nhà sàn tre bên cửa Sông Sương đổ ra biển, lưới phơi kín bãi. Khu nhỏ **Bến Sông Sương** là nơi Sương Mai luyện kiếm mỗi sáng.",secret:"Dưới gầm nhà trưởng làng có một chiếc thuyền nhỏ không bao giờ được hạ thủy. Người ta nói đó là thuyền của con trai Bà Lưới.",at:"dir:200:22"},{id:"pho-van-dang",name:"Phố Vạn Đăng",lore:"Thủ phủ, phố cảng mái ngói rêu phong, đêm nào cũng treo hàng nghìn đèn lồng. Có **Đình Trống Đồng** (trụ sở Hội Đồng, giữ trống đồng cổ nhất), chợ đêm, bến thuyền buôn. Trên đồi phía sau là **Phố Cũ**, nơi Mai Linh mở hàng đèn.",secret:"Đèn lồng đầu tiên của Nàng Vạn Đăng vẫn treo ở góc một con hẻm trong Phố Cũ và chưa bao giờ tắt. Không ai biết ai châm dầu cho nó.",at:"start"},{id:"rung-truc-may",name:"Rừng Trúc Mây",lore:"Rừng trúc phía tây, thân trúc cao đến mức ngọn chìm trong mây thấp. Gió qua rừng tạo tiếng như sáo. Nơi ở của Yêu Rừng.",secret:"Có một lối đi chỉ hiện ra khi trăng non, dẫn tới một khoảng đất trống có bàn cờ đá. Không ai biết ai đã chơi dở ván cờ trên đó.",at:"dir:250:28"},{id:"ho-guong-va-den-trang",name:"Hồ Gương và Đền Trăng",lore:"Hồ tròn hoàn hảo giữa đảo, mặt nước phẳng như gương. Đền Trăng mái cong nằm bên bờ, có chuông bạc, chỉ mở cửa trong cho khách vào đêm rằm. Bà Khơi ngủ dưới đáy hồ.",secret:"Vào những đêm không trăng, mặt hồ phản chiếu bầu trời của ba trăm năm trước. Thủy Nguyệt biết chuyện này và giữ kín.",at:"center"},{id:"dinh-vong-van",name:"Đỉnh Vọng Vân",lore:"Đỉnh núi cao nhất đảo ở phía bắc, có **Đài Đếm Sao** của Người Đếm Sao. Phong Vân lớn lên ở đây.",secret:"Trên vách đá sau đài có một danh sách tên được khắc rồi bị đục xóa. Một trong những tên đó là Tô Khuyết.",at:"dir:280:40"},{id:"mo-ngoc-long-chao",name:"Mỏ Ngọc Lòng Chảo",lore:"Mỏ ngọc bích trong một thung lũng hình lòng chảo dưới chân núi. Phường Đá Ngọc khai thác ở đây. Ngọc Thạch là con gái một thợ mỏ ở đây.",secret:"Tầng sâu nhất của mỏ đã bị bịt từ NS 1052, vì từ đó nghe được tiếng thở của Hắc Giao.",at:"statue:2"},{id:"vinh-khoi-va-lang-chim",name:"Vịnh Khơi và Làng Chìm",lore:"Vịnh phía đông, nơi Bà Khơi rơi xuống thời Bảy Sao Xuống và nơi Hắc Giao trồi lên năm NS 1046. Khi triều xuống thấp, thấy mái đình ba làng chìm.",secret:"Trong đình chìm lớn nhất vẫn còn một chiếc trống đồng. Gõ đúng nhịp ru của Bà Hiên thì nước quanh vịnh trong trở lại trong một đêm.",at:"dir:20:36"},{id:"thap-tinh-tu",name:"Tháp Tinh Tú",lore:"Tháp đá mười hai tầng dựng năm NS 1110 trên một vết sao rơi nhỏ ở phía đông bắc. Mỗi tầng khắc một chòm sao của lịch. Ánh sao rơi vào tháp rồi chảy xuống mạch sao nuôi bốn Bia Đá.",secret:"Có tầng thứ mười ba không có cầu thang, chỉ thấy được từ bên ngoài vào đêm sao rơi.",at:"tower"},{id:"hang-hac-giao",name:"Hang Hắc Giao",lore:"Hang sâu dưới núi phía bắc, miệng hang có bốn Bia Đá cổ trấn ở bốn hướng: Bia Đông, Bia Tây, Bia Nam, Bia Bắc. Nước trong hang đen như mực.",secret:"Bia Bắc khắc tên Hà Thanh. Ai đứng trước bia này lâu sẽ nghe một giọng con gái đếm nhịp thở.",at:"gate"}]},ni={quests:[{id:"tieng-goi-bia-da",type:"chinh",name:"Tiếng gọi của Bia Đá",giver:"Quan Trấn Thủ Cao Lũy",desc:"Cậu tỉnh dậy trên Bãi Sao Rơi mà không nhớ đường về. Người ta bảo cứ tìm Bia Đá, đá cổ sẽ giữ cho cậu một chỗ để quay lại.",steps:[{text:"Chạm Bia Đá gần nơi xuất phát",kind:"objective",id:"bia-da",target:"statue"},{text:"Mở rương báu trên đảo ({n}/{max})",kind:"objective",id:"ruong-dau",target:"chest"}],reward:"60 Đá Sao (qua rương)"},{id:"thap-mo-cua",type:"chinh",name:"Tháp mở cửa",giver:"Đầu Sổ Kỳ Lam",desc:"Ánh sao rơi vào Tháp Tinh Tú rồi chảy về bốn Bia Đá. Dạo này dòng ấy yếu đi. Đầu Sổ muốn biết tầng đầu còn ai canh không.",steps:[{text:"Vượt tầng 1 Tháp Tinh Tú",kind:"objective",id:"thap",target:"tower"},{text:"Vượt tầng 3 ({n}/{max})",kind:"tower",count:3,target:"tower"}],reward:"Đá Sao, Xu, Sách Kinh Nghiệm theo tầng"},{id:"nuoc-den-duoi-nui",type:"chinh",name:"Nước đen dưới núi",giver:"Bà Cả Thu Vọng",desc:"Nước trong hang phía bắc đen như mực. Bà Cả không nói gì thêm, chỉ đưa cho cậu một nắm muối và bảo đi sớm về sớm.",steps:[{text:"Tìm hang Hắc Giao và đánh bại ác long",kind:"objective",id:"hac-giao",target:"gate"}],reward:"300 Đá Sao, Vảy rơi từ trận đánh"},{id:"don-duong-lang",type:"phu",name:"Dọn đường cho làng",giver:"Bà Bảy Sóng",desc:"Giọt Nhầy và Yêu Rừng chặn lối mang cá lên chợ. Bà Bảy Sóng trả công bằng một nụ cười to và lời hứa chở hàng miễn phí.",steps:[{text:"Hạ quái quanh đảo ({n}/{max})",kind:"kills",count:30,target:"camp"}],reward:"Xu và tiếng thơm ở chợ đêm"},{id:"hai-nguyen-to",type:"phu",name:"Khi hai ngôi sao gặp nhau",giver:"Đầu Sổ Kỳ Lam",desc:'"Một vì sao thì sáng. Hai vì sao chạm nhau thì nổ." Đầu Sổ muốn cậu thử cho bà nghe.',steps:[{text:"Tạo phản ứng nguyên tố ({n}/{max})",kind:"reacts",count:10,target:"camp"}],reward:"Một dòng ghi trong sổ sao"},{id:"nguoi-tim-den",type:"phu",name:"Những người tìm đến",giver:"Bà Trùm Kha",desc:"Mỗi lần có lời ước được đáp, một Hộ Tinh lại tìm về đảo. Bà Trùm Kha muốn khắc tên họ lên một tấm bia mới.",steps:[{text:"Ước nguyện ({n}/{max} lần)",kind:"pulls",count:10},{text:"Có Hộ Tinh trong đội ngũ ({n}/{max})",kind:"owned",count:6}],reward:"Tên cậu trên bia mới"},{id:"so-tay-nguoi-di-duong",type:"phu",name:"Sổ tay người đi đường",giver:"Đầu Sổ Kỳ Lam",desc:"Thấy gì thì ghi lại. Một con cua, một cái tên, một hòn đá lạ. Người Đếm Sao tin rằng không có gì là nhỏ.",steps:[{text:"Mở mục trong Bách khoa ({n}/{max})",kind:"codex",count:15}],reward:"Bách khoa đầy hơn"}]},ii={shots:{s1:2.6,s2:2.2,s3:2.3,s4:1.9},slowMo:.28,videos:{},videoTimeoutMs:4e3},ti={login:{algo:"PBKDF2-SHA256",iterations:12e4,salt:"tinhtu-s10-mac-dinh",hash:"fb7b5bb46412950a1e8abfaeb4e82b457dbebfa162580e91da46d334f34496ad"},sessionMinutes:120},qn=s().regex(/^(start|center|tower|gate|statue:\d|dir:-?\d+:\d+)$/,"neo bản đồ không hợp lệ"),x=s().regex(/^[a-z0-9-]+$/),ai=c({main:l(c({id:x,name:s(),icon:s(),group:s(),hint:s()})).min(1),quick:l(x),transitionMs:b().int().positive().max(250),combatLock:c({radius:b().positive(),message:s()}),affinity:c({perSecond:b().nonnegative(),perKill:b().nonnegative(),levels:l(b().positive()).length(9)}),profile:l(c({file:x,name:s(),level:b().int().min(1).max(10),perSection:b().int().min(0)})),npcs:l(c({id:x,name:s(),role:s(),at:qn})),map:c({zoomMin:b().positive(),zoomMax:b().positive(),maxMarks:b().int().positive()})}),oi=c({types:l(c({id:x,name:s(),icon:s()})),drops:O(l(c({chance:b().min(0).max(1),pool:l(x).min(1)}))),items:l(c({id:x,name:s(),type:x,rarity:rn([K(3),K(4),K(5)]),region:s(),story:s().min(1),weapon:s().optional(),profileKey:C(["books"]).optional()}))}),hi=c({creatures:l(c({id:x,name:s(),tag:s().nullable(),habitat:s().nullable().optional(),lore:s().nullable().optional(),weak:s().nullable().optional(),rumor:s().nullable().optional(),inGame:A()})),places:l(c({id:x,name:s(),lore:s(),secret:s().nullable(),at:qn}))}),gi=["objective","kills","reacts","chests","tower","boss","pulls","owned","codex"],ei=c